#include <stdio.h>

enum Kind { KIND_INT, KIND_DOUBLE };

struct Value {
    enum Kind kind;            /* which member is active. */
    union {
        int i;
        double d;
    } as;                      /* i and d share the same bytes. */
};

struct Value make_int(int x)       { return (struct Value){.kind = KIND_INT, .as.i = x}; }
struct Value make_double(double x) { return (struct Value){.kind = KIND_DOUBLE, .as.d = x}; }

void print_value(const struct Value *v) {
    switch (v->kind) {
    case KIND_INT:    printf("int %d\n", v->as.i); break;
    case KIND_DOUBLE: printf("double %.2f\n", v->as.d); break;
    }
}

int main(void) {
    struct Value a = make_int(42), b = make_double(2.5);
    print_value(&a);           /* int 42. */
    print_value(&b);           /* double 2.50. */
    return 0;
}
